-- Prediction Query
SELECT T.team_long_name FROM (SELECT ta.team_api_id, ta.chanceCreationPassing, AVG(ta.chanceCreationPassing) OVER () AS avg_chance_creation_passing FROM Team_Attributes AS ta WHERE ta.buildUpPlayDribblingClass = 'Normal' AND ta."date" >= '2014-01-01 00:00:00' AND ta."date" <= '2014-12-31 23:59:59') AS subquery JOIN Team AS T ON subquery.team_api_id = T.team_api_id WHERE subquery.chanceCreationPassing < subquery.avg_chance_creation_passing ORDER BY subquery.chanceCreationPassing DESC, T.id NULLS LAST;

